async def act(page):
    """
    Locate orders with a Status of "Suspected Fraud" on the currently-visible
    Sales > Orders grid and return the customer name for the earliest (oldest)
    such order by the "Purchased On" date where available.

    This function continues from the current page state (does not re-navigate).
    """
    import datetime
    import re

    # Small pause to let any dynamic UI settle
    await page.wait_for_timeout(500)

    # Helper: normalize NBSP and strip
    def _clean(s: str) -> str:
        if not s:
            return ""
        return s.replace('\u00A0', ' ').strip()

    # Robust parser for grid date text like: "May 30, 2023 11:55:09 PM"
    def _parse_date_text(s: str):
        if not s:
            return None
        s = _clean(s)
        # Use only the first line which usually contains the date/time
        s = s.splitlines()[0].strip()
        fmts = [
            '%B %d, %Y %I:%M:%S %p',  # May 30, 2023 11:55:09 PM
            '%b %d, %Y %I:%M:%S %p',
            '%B %d, %Y %I:%M %p',
            '%b %d, %Y %I:%M %p',
            '%B %d, %Y',
            '%b %d, %Y',
            '%Y-%m-%d %H:%M:%S',
            '%Y-%m-%d',
        ]
        for fmt in fmts:
            try:
                return datetime.datetime.strptime(s, fmt)
            except Exception:
                pass
        # Try to find an ISO-like date
        m = re.search(r'(\d{4}-\d{1,2}-\d{1,2})', s)
        if m:
            try:
                return datetime.datetime.fromisoformat(m.group(1))
            except Exception:
                pass
        # Last resort: month name pattern
        m = re.search(r'([A-Za-z]{3,9}\s+\d{1,2},?\s+\d{4})', s)
        if m:
            for fmt in ('%B %d, %Y', '%b %d, %Y'):
                try:
                    return datetime.datetime.strptime(m.group(1).replace(',', ''), fmt)
                except Exception:
                    pass
        return None

    # 1) Find the orders table by scanning all tables for header text
    tables = page.get_by_role('table')
    tables_count = await tables.count()
    orders_table = None
    for i in range(tables_count):
        t = tables.nth(i)
        try:
            txt = (await t.inner_text()) or ''
        except Exception:
            txt = ''
        low = txt.lower()
        if 'order #' in low and 'status' in low:
            orders_table = t
            break
    if orders_table is None:
        raise RuntimeError('Could not find the orders table with expected headers')

    # 2) Get rows and determine header row index
    rows = orders_table.get_by_role('row')
    rows_count = await rows.count()
    if rows_count == 0:
        raise RuntimeError('Orders table contains no rows')

    header_idx = None
    for i in range(min(rows_count, 10)):
        r = rows.nth(i)
        try:
            rtxt = (await r.inner_text()) or ''
        except Exception:
            rtxt = ''
        low = rtxt.lower()
        if 'order #' in low and 'status' in low:
            header_idx = i
            break
    if header_idx is None:
        # conservative default to first row
        header_idx = 0

    header = rows.nth(header_idx)
    header_cells = header.get_by_role('cell')
    header_cells_count = await header_cells.count()

    status_idx = None
    customer_idx = None
    date_idx = None

    for j in range(header_cells_count):
        try:
            ctext = (await header_cells.nth(j).inner_text()) or ''
        except Exception:
            ctext = ''
        low = ctext.lower()
        if status_idx is None and 'status' in low:
            status_idx = j
        # Customer column can be labeled 'Bill to Name' or 'Ship to Name' or similar
        if customer_idx is None and ('bill to name' in low or 'bill to' in low or 'ship to name' in low or 'customer' in low):
            customer_idx = j
        if date_idx is None and any(k in low for k in ('purchased on', 'purch', 'date', 'created')):
            date_idx = j

    if status_idx is None or customer_idx is None:
        raise RuntimeError('Could not determine Status and Customer column indices from the header')

    # 3) Find the filter row (likely immediately after header) and locate a combobox option for Suspected Fraud
    filter_row_idx = None
    suspect_combobox = None
    suspect_option_label = None

    for k in range(header_idx + 1, min(rows_count, header_idx + 6)):
        r = rows.nth(k)
        cbs = r.get_by_role('combobox')
        try:
            cbcount = await cbs.count()
        except Exception:
            cbcount = 0
        if cbcount == 0:
            continue
        for cb_i in range(cbcount):
            cb = cbs.nth(cb_i)
            opts = []
            try:
                # gather option visible texts
                opts = await cb.get_by_role('option').all_inner_texts()
            except Exception:
                try:
                    opts_text = (await cb.inner_text()) or ''
                    opts = [opts_text]
                except Exception:
                    opts = []
            for opt in opts:
                if 'suspected fraud' in opt.lower() or ('suspect' in opt.lower() and 'fraud' in opt.lower()):
                    suspect_option_label = opt
                    suspect_combobox = cb
                    filter_row_idx = k
                    break
            if suspect_combobox:
                break
        if suspect_combobox:
            break

    # If we found the combobox+option, select it and click the Search button in the toolbar
    if suspect_combobox and suspect_option_label:
        await suspect_combobox.select_option(label=suspect_option_label)
        # find toolbar table containing Export/Search controls
        toolbar_table = None
        for i in range(tables_count):
            t = tables.nth(i)
            try:
                ttxt = (await t.inner_text()) or ''
            except Exception:
                ttxt = ''
            if 'export to' in ttxt.lower() and 'search' in ttxt.lower():
                toolbar_table = t
                break
        if toolbar_table is not None:
            search_buttons = toolbar_table.get_by_role('button', name='Search')
            if await search_buttons.count() > 0:
                # use scoped button click
                await search_buttons.nth(0).click()
        # wait for grid to refresh
        await page.wait_for_timeout(1000)

    # 4) Iterate data rows (start after header and filters) and collect suspected-fraud rows
    start_idx = header_idx + 1
    if filter_row_idx is not None and filter_row_idx >= start_idx:
        start_idx = filter_row_idx + 1

    fraud_rows = []  # tuples: (parsed_datetime_or_None, customer_text, raw_date_text)

    for r_i in range(start_idx, rows_count):
        row = rows.nth(r_i)
        cells = row.get_by_role('cell')
        try:
            cells_count = await cells.count()
        except Exception:
            cells_count = 0
        if cells_count == 0:
            # not a data row
            continue

        # If the row doesn't have enough cells for indexed access, check row text as fallback
        if max(status_idx, customer_idx, (date_idx if date_idx is not None else 0)) >= cells_count:
            try:
                row_text = (await row.inner_text()) or ''
            except Exception:
                row_text = ''
            low_row = row_text.lower()
            if 'fraud' in low_row or 'suspect' in low_row:
                first_line = row_text.splitlines()[0] if row_text else ''
                fraud_rows.append((None, _clean(first_line), ''))
            continue

        try:
            status_text = (await cells.nth(status_idx).inner_text()) or ''
        except Exception:
            status_text = ''
        low_status = status_text.lower()

        if 'suspected fraud' in low_status or ('suspect' in low_status and 'fraud' in low_status) or ('fraud' in low_status and 'suspect' in low_status):
            try:
                customer_text = (await cells.nth(customer_idx).inner_text()) or ''
            except Exception:
                customer_text = ''
            customer_text = _clean(customer_text)
            raw_date = ''
            parsed = None
            if date_idx is not None and date_idx < cells_count:
                try:
                    raw_date = (await cells.nth(date_idx).inner_text()) or ''
                    parsed = _parse_date_text(raw_date)
                except Exception:
                    parsed = None
            fraud_rows.append((parsed, customer_text, raw_date))

    if not fraud_rows:
        raise RuntimeError('No fraud-suspect orders found in the orders grid')

    # Prefer rows with parsed dates; choose the earliest (oldest) date. If none parsed, fall back to last matched row.
    rows_with_dates = [r for r in fraud_rows if r[0] is not None]
    if rows_with_dates:
        earliest = min(rows_with_dates, key=lambda x: x[0])
    else:
        earliest = fraud_rows[-1]

    customer_name = earliest[1].strip()
    return customer_name

